/**
 * A Button preset for signing in with an identity provider (`design/components/provider-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/provider-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  BrandMark,
  Icon,
  agentMember,
  agentPress,
  claimSlot,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/provider-button.module.css'

export type ProviderButtonProvider = ProviderButtonProps['provider']

export interface ProviderButtonProps {
  /**
   * Links supporting text, such as "Your organization requires single sign-on", to the button.
   */
  'aria-describedby'?: string
  disabled?: boolean
  /**
   * The full label in the app's language, such as "Continue with Google". It is required and
   * passed whole, because the vocabulary has no built-in text, word order around a brand name
   * differs by language, and the provider's terms govern the wording.
   */
  label: string
  /**
   * The sign-in flow has started and not finished. Keeps focus, colours and name, and ignores
   * presses.
   */
  loading?: boolean
  onClick?: (event: MouseEvent) => void
  /**
   * Which mark is drawn, from `BrandMark`'s fixed set.
   */
  provider: 'google' | 'microsoft' | 'github'
  size?: 'sm' | 'md' | 'lg'
  type?: 'button' | 'submit'
}

/** A Button preset for signing in with an identity provider. */
export default function ProviderButton(given: ProviderButtonProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', loading: false, disabled: false, type: 'button' } as Defaults<
      ProviderButtonProps,
      'size' | 'loading' | 'disabled' | 'type'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const control = elementRef<HTMLElement>()
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ProviderButton',
        element: () => control.value,
        state: () => ({ disabled: props.disabled, loading: props.loading }),
        actions: { press: () => agentPress(control.value) },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <button
        class={styles.button}
        type={props.type}
        disabled={props.disabled}
        aria-busy={props.loading ? true : undefined}
        aria-describedby={props['aria-describedby']}
        data-variant="outline"
        data-tone="neutral"
        data-size={props.size}
        data-state={props.loading ? 'loading' : undefined}
        data-disabled={props.disabled ? '' : undefined}
        data-provider={props.provider}
        data-member="provider-button"
        onclick={($event: MouseEvent) => !props.loading && props.onClick?.($event)}
        ref={control.attach}
      >
        {props.loading ? (
          <span class={styles.spinner}>
            <Icon name="loading" size={props.size} />
          </span>
        ) : (
          <span class={styles.mark}>
            <Dynamic component={BrandMark} name={props.provider} size={props.size} />
          </span>
        )}
        {/* label */}
        <span class={styles.label}>{props.label}</span>
      </button>
    )
  })
}
